window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[235]={"id":"235","numero":235,"titre":"Péricardite aiguë","objectifs":[{"id":"235-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une péricardite aiguë","contenu":"<p>La péricardite aiguë est une <span class=\"kw-def\">inflammation aiguë des feuillets péricardiques</span> (feuillets viscéral et pariétal du péricarde).</p>\n      <ul>\n        <li>Elle peut être <strong>accompagnée d'un <span class=\"kw-clinique\">épanchement péricardique</span></strong> ou non — on parle alors de <span class=\"kw-def\">« péricardite sèche »</span> lorsqu'il n'y a pas d'épanchement.</li>\n        <li>Lorsqu'elle est associée à une élévation de la <span class=\"kw-bio\">troponine</span>, on parle de <strong><span class=\"kw-def\">myo-péricardite</span></strong> (atteinte myocardique associée).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Péricardite « sèche » = sans épanchement ; <span class=\"kw-bio\">troponine</span> élevée = myo-péricardite, à ne pas confondre avec un <span class=\"kw-def\">syndrome coronarien aigu</span>.</div>","frequence":0},{"id":"235-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> repose sur un faisceau de critères. Le <span class=\"kw-def\">terrain</span> typique est un <strong>sujet jeune</strong>, avec une <span class=\"kw-etio\">prédominance masculine</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Critères diagnostiques</span> EDN — <span class=\"kw-chiffre\">≥ 2</span>/4 critères</h4>\n      <p>Le diagnostic est retenu devant la présence d'au moins <span class=\"kw-chiffre\">2 critères sur 4</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur thoracique</span> d'allure péricarditique</li>\n        <li><span class=\"kw-clinique\">Frottement péricardique</span> à l'auscultation</li>\n        <li>Anomalies <span class=\"kw-imagerie\">ECG</span> typiques (<span class=\"kw-def\">stade</span> 1, ou sous-décalage PQ)</li>\n        <li><span class=\"kw-clinique\">Épanchement péricardique</span> (<span class=\"kw-imagerie\">ETT</span> systématique)</li>\n      </ul>\n      <p><strong>Critères additionnels :</strong> <span class=\"kw-def\">syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">VS</span> élevées ou hyperleucocytose) ; inflammation mise en évidence par <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-imagerie\">TDM</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">La <span class=\"kw-clinique\">douleur thoracique</span> péricarditique</h4>\n      <table >\n        <thead><tr><th>Caractère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Localisation</td><td>Rétrosternale ou précordiale gauche</td></tr>\n          <tr><td>Durée</td><td>Prolongée, permanente</td></tr>\n          <tr><td>Majorée par</td><td>Le <span class=\"kw-clinique\">décubitus</span> ; l'<span class=\"kw-clinique\">inspiration profonde</span> ; la <span class=\"kw-clinique\">toux</span> (douleur impulsive)</td></tr>\n          <tr><td>Calmée par</td><td>La position assise penchée en avant (<span class=\"kw-clinique\">antéflexion</span>) = attitude <span class=\"kw-ttt\">antalgique</span> en « prière mahométane »</td></tr>\n          <tr><td>Signes négatifs</td><td><span class=\"kw-alerte\">Résistante à la trinitrine</span> ; ne survient pas à l'effort</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Autres symptômes</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> modérée : présente d'emblée ; moins fréquente, voire absente, chez le sujet âgé</li>\n        <li><span class=\"kw-clinique\">Syndrome grippal</span> (<span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">asthénie</span>) précédant la péricardite de quelques jours</li>\n        <li>Parfois <span class=\"kw-clinique\">dyspnée</span> (également soulagée par l'antéflexion), <span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-clinique\">hoquet</span></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Signes physiques</h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Frottement péricardique</span></strong> : précoce, inconstant et <span class=\"kw-clinique\">fugace</span> (varie dans le temps et avec les positions) ; <span class=\"kw-clinique\">râpeux</span> (crissement de cuir neuf, froissement de soie, pas dans la neige) ; <span class=\"kw-clinique\">systolodiastolique</span></li>\n        <li><span class=\"kw-clinique\">Tachycardie</span> souvent présente</li>\n        <li>Signes d'<span class=\"kw-imagerie\">épanchement pleural</span> associé possibles : disparition du murmure vésiculaire, matité à la percussion</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> La présence de signes d'<span class=\"kw-alerte\">insuffisance cardiaque droite</span> doit faire suspecter une <span class=\"kw-alerte\">tamponnade</span> — ce n'est jamais banal dans une péricardite.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 230 — <span class=\"kw-clinique\">Douleur thoracique</span></em></p>","frequence":1},{"id":"235-3","rang":"A","rubrique":"Identification de l’urgence","titre":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","contenu":"<p>Les <span class=\"kw-alerte\">signes de gravité</span> doivent faire suspecter une <span class=\"kw-alerte\">tamponnade</span> ou une <span class=\"kw-alerte\">myocardite</span> associée. Ils s'évaluent dans 4 domaines.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th><span class=\"kw-alerte\">Signes de gravité</span></th></tr></thead>\n        <tbody>\n          <tr><td>Clinique</td><td>Signes de <span class=\"kw-alerte\">choc</span> ; signes d'<span class=\"kw-alerte\">insuffisance cardiaque droite</span> ; <span class=\"kw-alerte\">pouls paradoxal</span> ; <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 38 °C</span></td></tr>\n          <tr><td>Biologie</td><td>Élévation de la <span class=\"kw-bio\">troponine</span> (oriente vers une myocardite associée)</td></tr>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td><span class=\"kw-alerte\">Microvoltage</span> et <span class=\"kw-alerte\">alternance électrique</span> (<span class=\"kw-alerte\">tamponnade</span>) ; troubles du <span class=\"kw-alerte\">rythme ventriculaire</span> (myocardite)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">ETT</span></td><td>Épanchement <span class=\"kw-chiffre\">&gt; 20 mm</span> ; compression des cavités droites</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant une <span class=\"kw-alerte\">tamponnade</span> (épanchement abondant comprimant les cavités droites, retentissement hémodynamique), il faut appeler en <span class=\"kw-alerte\">urgence</span> pour un <strong><span class=\"kw-ttt\">drainage</span> de l'<span class=\"kw-imagerie\">épanchement péricardique</span></strong> — le <span class=\"kw-alerte\">pronostic vital</span> est engagé (risque d'arrêt cardio-circulatoire par adiastolie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"235-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","contenu":"<h4 style=\"margin:6px 0 6px;font-size:14px;\"><span class=\"kw-bio\">Électrocardiogramme</span></h4>\n      <p>L'<span class=\"kw-bio\">ECG</span> peut être <strong>normal</strong> — il faut alors le <span class=\"kw-alerte\">répéter</span>. Les anomalies sont <span class=\"kw-imagerie\">diffuses</span>, non systématisées, <strong>sans image en miroir</strong> (tétrade de Holtzman).</p>\n      <ul>\n        <li><strong>Signes précoces :</strong> <span class=\"kw-imagerie\">tachycardie sinusale</span> ; <span class=\"kw-imagerie\">sous-décalage du segment PQ</span> (repolarisation atriale, normalement non visible — témoin de l'inflammation auriculaire).</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Délai</th><th>Aspect <span class=\"kw-bio\">ECG</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Stade</span> 1</td><td><span class=\"kw-chiffre\">1ᵉʳ jour</span></td><td>Sus-décalage ST <span class=\"kw-imagerie\">concave vers le haut</span> + ondes T positives</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 2</td><td><span class=\"kw-chiffre\">24-48 h</span></td><td>Normalisation du segment ST + ondes T plates</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 3</td><td><span class=\"kw-chiffre\">1ʳᵉ semaine</span></td><td>Ondes T négatives</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 4</td><td><span class=\"kw-chiffre\">1ᵉʳ mois</span></td><td>Normalisation</td></tr>\n        </tbody>\n      </table>\n      <p><strong>En cas d'épanchement abondant :</strong> <span class=\"kw-alerte\">microvoltage</span> diffus (QRS <span class=\"kw-chiffre\">&lt; 5 mm</span> en périphérique, <span class=\"kw-chiffre\">&lt; 10 mm</span> en précordial) ; <span class=\"kw-alerte\">alternance électrique</span> (QRS d'amplitude variable, équivalent du <em>swinging heart</em> échographique).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Bilan <span class=\"kw-ttt\">biologique</span> initial</h4>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">CRP</span> : recherche d'un <span class=\"kw-def\">syndrome inflammatoire</span></li>\n        <li><span class=\"kw-bio\">Créatininémie</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">ionogramme sanguin</span> : recherche d'une <span class=\"kw-ci\">insuffisance rénale</span> <strong>avant la prescription d'<span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">colchicine</span></strong></li>\n        <li>Marqueurs de <span class=\"kw-clinique\">nécrose</span> myocardique — <span class=\"kw-bio\">troponines I ou T</span> (ultrasensibles), <span class=\"kw-bio\">CPK</span> : leur élévation évoque une <span class=\"kw-alerte\">myocardite associée</span></li>\n        <li><span class=\"kw-bio\">Hémocultures</span> si <span class=\"kw-clinique\">fièvre</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Le sus-décalage ST de la péricardite est <span class=\"kw-imagerie\">diffus, concave et sans miroir</span> — à l'opposé du <span class=\"kw-def\">SCA</span> (sus-décalage systématisé, convexe, avec miroir). Le sous-décalage PQ est très évocateur de péricardite.</div>","frequence":1},{"id":"235-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaitre l’intérêt diagnostique d’une ponction péricardique","contenu":"<p>La <span class=\"kw-def\">ponction péricardique</span> a un double intérêt : <strong>évacuateur</strong> (<span class=\"kw-ttt\">drainage</span>) et <strong>diagnostique</strong> (analyse du liquide).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Indications</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Tamponnade</span> (<span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span>)</li>\n        <li>Épanchement abondant et symptomatique <strong>malgré</strong> un traitement médical bien conduit depuis <span class=\"kw-chiffre\">1 semaine</span></li>\n        <li>Forte suspicion de péricardite <span class=\"kw-etio\">néoplasique</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Analyses du liquide péricardique</h4>\n      <ul>\n        <li><strong>Biochimie :</strong> <span class=\"kw-bio\">glucose</span>, <span class=\"kw-bio\">protides</span>, <span class=\"kw-bio\">lactates</span> déshydrogénase (<span class=\"kw-bio\">LDH</span>)</li>\n        <li><strong>Cytologie :</strong> recherche de cellules néoplasiques</li>\n        <li><strong>Bactériologie et virologie :</strong> Gram et <span class=\"kw-bio\">Ziehl-Neelsen</span>, culture, <span class=\"kw-bio\">PCR virale</span>, <span class=\"kw-bio\">PCR BK</span></li>\n      </ul>\n      <p><strong>Orientation étiologique par l'aspect macroscopique du liquide (LiSA)</strong> : <span class=\"kw-bio\">séreux/citrin</span> → péricardite virale ou idiopathique ; <span class=\"kw-bio\">purulent (louche)</span> → péricardite bactérienne ; <span class=\"kw-bio\">hémorragique</span> → péricardite <span class=\"kw-etio\">néoplasique</span>, <span class=\"kw-etio\">tuberculeuse</span> ou hémopéricarde (<span class=\"kw-alerte\">dissection aortique</span>, rupture de paroi post-IDM, traumatisme, iatrogène) ; <span class=\"kw-bio\">chyleux</span> → atteinte du canal thoracique.</p>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> En cas de suspicion de péricardite <span class=\"kw-etio\">purulente</span>, on privilégie un <strong><span class=\"kw-ttt\">drainage chirurgical</span></strong> (drain de plus gros calibre) plutôt qu'une simple <span class=\"kw-ttt\">ponction</span>.</div>","frequence":0},{"id":"235-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’objectif de l’imagerie dans l’exploration d’une péricardite aiguë : radiographie thoracique et échocardiographie","contenu":"<p>Le bilan d'imagerie initial associe <strong><span class=\"kw-bio\">ECG</span> + <span class=\"kw-imagerie\">radiographie thoracique</span> + <span class=\"kw-imagerie\">échocardiographie transthoracique</span> (<span class=\"kw-imagerie\">ETT</span>)</strong>. La <span class=\"kw-imagerie\">TDM</span> et l'<span class=\"kw-imagerie\">IRM</span> sont des examens de 2ᵉ intention.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Apport diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique</span> (<span class=\"kw-imagerie\">RXT</span>)</td><td>\n            <strong>Le plus souvent normale</strong><br>\n            Si épanchement abondant : <span class=\"kw-imagerie\">cardiomégalie symétrique</span>, cœur triangulaire « en carafe »<br>\n            Peut orienter l'étiologie (lésions pulmonaires, <span class=\"kw-imagerie\">épanchement pleural</span> associé)\n          </td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échocardiographie</span> (<span class=\"kw-imagerie\">ETT</span>)</td><td>\n            <strong>Peut être normale</strong> : péricardite « sèche » (sans épanchement)<br>\n            <span class=\"kw-imagerie\">Épaississement péricardique</span><br>\n            <span class=\"kw-imagerie\">Épanchement</span> : décollement des 2 feuillets, espace clair vide d'écho — abondance : minime <span class=\"kw-chiffre\">&lt; 10 mm</span>, modéré <span class=\"kw-chiffre\">10-20 mm</span>, abondant <span class=\"kw-chiffre\">&gt; 20 mm</span><br>\n            Arguments pour une origine <span class=\"kw-etio\">néoplasique</span> : <span class=\"kw-clinique\">masse</span>, métastases, caillots, bandes de <span class=\"kw-bio\">fibrine</span>, épanchement cloisonné\n          </td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span> thoracique / <span class=\"kw-imagerie\">IRM</span> cardiaque (2ᵉ intention)</td><td>\n            Patient peu échogène<br>\n            Suspicion de péricardite <span class=\"kw-etio\">néoplasique</span> ou épanchement cloisonné<br>\n            Suspicion de <span class=\"kw-alerte\">myocardite</span> associée (réhaussement tardif après gadolinium)\n          </td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/rxt-epanchement-pericardique.jpeg\" alt=\"Radiographie thoracique de face montrant une cardiomégalie symétrique en carafe par épanchement péricardique abondant\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie thoracique</span> — cardiomégalie symétrique « en carafe » témoignant d'un <span class=\"kw-imagerie\">épanchement péricardique</span> abondant. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ett-epanchement-pericardique.jpg\" alt=\"Échocardiographie transthoracique montrant un épanchement péricardique sous forme d'espace clair vide d'écho entre les deux feuillets\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Échocardiographie</span> transthoracique — <span class=\"kw-imagerie\">épanchement péricardique</span> : décollement des deux feuillets, visible comme un espace clair vide d'écho. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-imagerie\">ETT</span> est systématique : elle confirme l'épanchement, en précise l'abondance et la localisation, et recherche un retentissement hémodynamique (<span class=\"kw-alerte\">tamponnade</span>).</div>","frequence":3},{"id":"235-7","rang":"A","rubrique":"Contenu multimédia","titre":"Electrocardiogramme (ECG) d’une péricardite aiguë","contenu":"<p>L'<span class=\"kw-bio\">ECG</span> de péricardite aiguë présente des anomalies de repolarisation <span class=\"kw-imagerie\">diffuses</span>, <strong>non systématisées</strong>, <strong>sans image en miroir</strong> — c'est la <span class=\"kw-def\">tétrade de Holtzman</span>, qui évolue en 4 stades successifs.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ecg-pericardite-1.jpg\" alt=\"ECG de péricardite aiguë montrant un sus-décalage du segment ST concave vers le haut diffus et un sous-décalage du segment PQ\" loading=\"lazy\">\n        <figcaption><span class=\"kw-bio\">ECG</span> de péricardite aiguë — sus-décalage ST concave vers le haut, diffus, sans miroir ; sous-décalage du segment PQ. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/ecg-pericardite-2.png\" alt=\"Second tracé ECG de péricardite aiguë illustrant des anomalies de repolarisation diffuses non systématisées\" loading=\"lazy\">\n        <figcaption><span class=\"kw-bio\">ECG</span> de péricardite aiguë (2ᵉ tracé) — anomalies de repolarisation diffuses dans toutes les dérivations sauf aVR et V1. Source : fiche source EDN item 235.</figcaption>\n      </figure>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Lecture commentée</h4>\n      <ul>\n        <li><strong>Signes précoces :</strong> <span class=\"kw-imagerie\">tachycardie sinusale</span> ; <span class=\"kw-imagerie\">sous-décalage du segment PQ</span> (repolarisation atriale, témoin de l'inflammation des oreillettes).</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 1</strong> (1ᵉʳ jour) : sus-décalage ST <span class=\"kw-imagerie\">concave vers le haut</span> + ondes T positives.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 2</strong> (<span class=\"kw-chiffre\">24-48 h</span>) : normalisation du ST + ondes T plates.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 3</strong> (1ʳᵉ semaine) : ondes T négatives.</li>\n        <li><strong><span class=\"kw-def\">Stade</span> 4</strong> (1ᵉʳ mois) : normalisation.</li>\n        <li><strong>Si épanchement abondant :</strong> <span class=\"kw-alerte\">microvoltage</span> diffus et <span class=\"kw-alerte\">alternance électrique</span> (équivalent électrique du <em>swinging heart</em>).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Anomalies <span class=\"kw-imagerie\">diffuses, concaves, sans miroir</span> = péricardite. Sus-décalage <span class=\"kw-alerte\">systématisé, convexe, avec miroir</span> = <span class=\"kw-def\">SCA</span>. Le <span class=\"kw-imagerie\">sous-décalage PQ</span> est quasi pathognomonique de péricardite.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/pericarditis","label":"Radiopaedia : Pericarditis"},{"href":"https://radiopaedia.org/articles/cardiac-tamponade","label":"Radiopaedia : Cardiac tamponade"}]},{"id":"235-8","rang":"A","rubrique":"Prise en charge","titre":"Savoir évaluer les risques de complications nécessitant une hospitalisation","contenu":"<p>L'<span class=\"kw-alerte\">hospitalisation</span> <strong>n'est pas systématique</strong>. Elle est envisagée en cas de risque de complication et/ou d'étiologie inhabituelle (&lt;<span class=\"kw-chiffre\"> 20 %</span> des cas), selon des facteurs prédictifs.</p>\n      <table >\n        <thead><tr><th>Facteurs prédictifs majeurs</th><th>Facteurs prédictifs mineurs</th></tr></thead>\n        <tbody>\n          <tr><td>\n            <span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">&gt; 38 °C</span><br>\n            Symptômes depuis plusieurs jours/semaines avec début <span class=\"kw-clinique\">subaigu</span><br>\n            Épanchement abondant (<span class=\"kw-chiffre\">&gt; 20 mm</span>) ou <span class=\"kw-alerte\">tamponnade</span><br>\n            <span class=\"kw-alerte\">Résistance</span> au traitement anti-<span class=\"kw-etio\">inflammatoire</span> depuis <span class=\"kw-chiffre\">&gt; 7 jours</span>\n          </td><td>\n            Patient <span class=\"kw-etio\">immunodéprimé</span><br>\n            Patient sous <span class=\"kw-ttt\">anticoagulant</span><br>\n            Suites d'un <span class=\"kw-etio\">traumatisme thoracique</span><br>\n            <span class=\"kw-alerte\">Myocardite</span> associée (élévation des <span class=\"kw-bio\">troponines</span>)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La présence d'un seul facteur majeur, ou d'un faisceau de facteurs mineurs, justifie l'<span class=\"kw-alerte\">hospitalisation</span> et la recherche d'une étiologie non bénigne.</div>","frequence":1},{"id":"235-9","rang":"A","rubrique":"Etiologies","titre":"Connaître l’étiologie de la forme clinique usuelle","contenu":"<p>La forme clinique usuelle est la <strong>péricardite <span class=\"kw-etio\">virale ou idiopathique</span></strong> — c'est l'étiologie dominante (<span class=\"kw-chiffre\">90 %</span> des cas), liée à l'infection <span class=\"kw-etio\">virale</span> et à la réaction immune associée. Elle est rarement prouvée.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Virus en cause</td><td><span class=\"kw-etio\">Entérovirus</span> (Coxsackie A et B), échovirus, adénovirus, <span class=\"kw-etio\">CMV</span>, EBV, herpès, parvovirus B19, VIH, VHC, influenza, COVID-19</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Sujet <span class=\"kw-clinique\">jeune</span>, prédominance <span class=\"kw-etio\">masculine</span>, sans antécédent cardiologique notable</td></tr>\n          <tr><td>Présentation</td><td><span class=\"kw-clinique\">Syndrome grippal</span> récent ; début <span class=\"kw-clinique\">brutal</span> (<span class=\"kw-clinique\">fièvre</span>, douleur typique, frottement) ; modifications <span class=\"kw-bio\">ECG</span> typiques ; <span class=\"kw-imagerie\">ETT le plus souvent normale</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Le plus souvent <strong>favorable</strong> ; taux de récidive important (<span class=\"kw-chiffre\">30-50 %</span>) ; complications rares hors récidive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Dans une forme typique, les <span class=\"kw-bio\">recherches virologiques</span> (<span class=\"kw-bio\">sérologies</span>, <span class=\"kw-bio\">PCR</span>) sont <strong>inutiles</strong> : elles n'ont pas d'implication thérapeutique. Le diagnostic est clinique.</div>\n      <p><strong>Focus <span class=\"kw-etio\">VIH</span> :</strong> la péricardite liée au VIH s'accompagne fréquemment d'un épanchement, par des mécanismes multiples — infection par le VIH lui-même, surinfection <span class=\"kw-etio\">bactérienne</span> ou fongique chez l'immunodéprimé, ou présence d'un <span class=\"kw-etio\">lymphome</span> / <span class=\"kw-etio\">sarcome de Kaposi</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"235-10","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies de la péricardite au cours d’un infarctus du myocarde","contenu":"<p>Au décours d'un <span class=\"kw-def\">infarctus du myocarde</span>, deux types de péricardite sont à connaître, distincts par leur délai et leur mécanisme.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Délai</th><th>Présentation / <span class=\"kw-clinique\">évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td>Péricardite précoce (épisténocardique)</td><td><span class=\"kw-chiffre\">J3-J5</span></td><td>\n            Habituellement <span class=\"kw-etio\">inflammatoire</span>, associée à un <span class=\"kw-def\">IDM</span> étendu<br>\n            Au décours d'un <span class=\"kw-clinique\">infarctus</span> transmural : possible <span class=\"kw-alerte\">hémopéricarde</span><br>\n            <span class=\"kw-clinique\">Évolution</span> souvent favorable si minime ; <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span> en cas de <span class=\"kw-alerte\">rupture</span> myocardique\n          </td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome de Dressler</span></td><td><span class=\"kw-chiffre\">2ᵉ-16ᵉ semaine</span> (classiquement la 3ᵉ)</td><td>\n            Origine <span class=\"kw-etio\">immunologique</span> (libération antigénique du tissu nécrosé)<br>\n            Tableau : <span class=\"kw-clinique\">AEG</span> ; <span class=\"kw-clinique\">fièvre</span> ; péricardite (épanchement) ; <span class=\"kw-imagerie\">épanchement pleural</span> ; <span class=\"kw-clinique\">arthralgies</span><br>\n            <span class=\"kw-bio\">ECG</span> : <span class=\"kw-imagerie\">allongement du QT</span><br>\n            Biologie : <span class=\"kw-def\">syndrome inflammatoire</span> important ; <span class=\"kw-clinique\">évolution</span> favorable sous traitement anti-<span class=\"kw-etio\">inflammatoire</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0},{"id":"235-11","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies de formes cliniques moins fréquentes","contenu":"<p>En dehors de la forme <span class=\"kw-etio\">virale</span>/idiopathique (<span class=\"kw-chiffre\">90 %</span>), de nombreuses étiologies plus rares sont à connaître — certaines graves.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Infectieuse</td><td>\n            <strong>Purulente :</strong> rare mais grave (<span class=\"kw-etio\">staphylocoque</span>, <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">streptocoque</span>, BGN) ; <span class=\"kw-def\">terrain</span> immunodéprimé ou infection sévère<br>\n            <strong>Tuberculeuse :</strong> sujet âgé, greffé, <span class=\"kw-etio\">VIH</span>, alcoolique ; risque de <span class=\"kw-alerte\">constriction péricardique</span>\n          </td></tr>\n          <tr><td><span class=\"kw-etio\">Néoplasique</span></td><td>\n            Tumeurs <strong>secondaires</strong> +++ : bronche, sein, <span class=\"kw-clinique\">mélanome</span>, leucémie, lymphome, sarcome de Kaposi<br>\n            Tumeurs primitives rares (mésothéliome péricardique), 40× moins fréquentes que les métastases\n          </td></tr>\n          <tr><td>Maladies systémiques auto-immunes</td><td>\n            <span class=\"kw-etio\">Lupus</span>, <span class=\"kw-def\">polyarthrite rhumatoïde</span>, sclérodermie, périartérite noueuse, dermatomyosite<br>\n            Reste un diagnostic d'élimination\n          </td></tr>\n          <tr><td><span class=\"kw-ci\">Insuffisance rénale</span></td><td>\n            <strong>Urémique</strong> (patient non dialysé ou début de dialyse) : exsudat <span class=\"kw-etio\">inflammatoire</span><br>\n            <strong>De l'hémodialysé</strong> : transsudat par surcharge volémique, témoin d'une épuration inadaptée\n          </td></tr>\n          <tr><td>Post-péricardotomie</td><td>\n            Origine <span class=\"kw-etio\">inflammatoire</span> après <span class=\"kw-ttt\">chirurgie</span> cardiaque ou transplantation<br>\n            La chirurgie cardiaque est la <strong>1ʳᵉ cause de constriction péricardique</strong>\n          </td></tr>\n          <tr><td>Autres</td><td>\n            <span class=\"kw-etio\">Hypothyroïdie</span><br>\n            <span class=\"kw-etio\">Médicamenteuse</span> : <span class=\"kw-ttt\">hydralazine</span>, <span class=\"kw-ttt\">pénicilline</span><br>\n            <span class=\"kw-etio\">Radique</span> : ~<span class=\"kw-chiffre\">1 an</span> après l'<span class=\"kw-clinique\">irradiation</span> thoracique (cancer du sein gauche, lymphome), risque d'<span class=\"kw-clinique\">évolution</span> constrictive<br>\n            <span class=\"kw-alerte\">Dissection aortique</span> avec <span class=\"kw-alerte\">tamponnade</span> ; traumatisme thoracique (hémopéricarde) ; rhumatisme articulaire aigu\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Péricardite <span class=\"kw-etio\">purulente</span> et <span class=\"kw-etio\">tuberculeuse</span> = formes graves à fort risque de <span class=\"kw-alerte\">tamponnade</span> et de <span class=\"kw-alerte\">constriction</span> ; toute péricardite chronique (&gt;<span class=\"kw-chiffre\"> 3 mois</span>) doit faire suspecter une cause tuberculeuse ou <span class=\"kw-etio\">néoplasique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 169 — <span class=\"kw-etio\">VIH</span> · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":1},{"id":"235-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’une péricardite aiguë bénigne","contenu":"<h4 style=\"margin:6px 0 6px;font-size:14px;\">Mesures générales</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Repos</span> jusqu'à disparition des symptômes et normalisation des examens (<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">ETT</span>) — en général le 1ᵉʳ mois</li>\n        <li>Arrêt de travail</li>\n        <li>Traitement de la <span class=\"kw-clinique\">douleur thoracique</span></li>\n        <li>Protecteur gastrique associé en cas de bithérapie anti-<span class=\"kw-etio\">inflammatoire</span></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement <span class=\"kw-etio\">médicamenteux</span> — bithérapie anti-<span class=\"kw-etio\">inflammatoire</span> prolongée</h4>\n      <table >\n        <thead><tr><th>Médicament</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">AINS</span></td><td>\n            Attaque <span class=\"kw-chiffre\">1 à 2 semaines</span> : <span class=\"kw-ttt\">ibuprofène</span> <span class=\"kw-chiffre\">600-800 mg ×3/j</span> ou <span class=\"kw-ttt\">aspirine</span> <span class=\"kw-chiffre\">750-1000 mg ×3/j</span><br>\n            Arrêt progressif selon symptômes, <span class=\"kw-bio\">CRP</span> et absence d'épanchement à l'<span class=\"kw-imagerie\">ETT</span> — durée totale <span class=\"kw-chiffre\">4 à 8 semaines</span>\n          </td></tr>\n          <tr><td><span class=\"kw-ttt\">Colchicine</span></td><td>\n            <span class=\"kw-chiffre\">0,5 mg ×1/j</span> (poids &lt;<span class=\"kw-chiffre\"> 70 kg</span>) ou <span class=\"kw-chiffre\">×2/j</span> (poids &gt;<span class=\"kw-chiffre\"> 70 kg</span>)<br>\n            Durée <span class=\"kw-chiffre\">3 mois</span> ; diminue la douleur, la durée des symptômes et réduit le risque de récidive de <span class=\"kw-chiffre\">50 %</span>\n          </td></tr>\n          <tr><td><span class=\"kw-ttt\">Corticoïdes</span></td><td>\n            <span class=\"kw-chiffre\">0,25-0,5 mg/kg/j</span>, en association — <strong>uniquement en 2ᵉ intention en cas d'échec</strong>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Pas de <span class=\"kw-ci\">corticoïdes en 1ʳᵉ intention</span> dans la péricardite aiguë bénigne — ils favorisent les récidives.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Rappels sur la <span class=\"kw-ttt\">colchicine</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-ci\">Contre-indication</span> :</strong> <span class=\"kw-ci\">insuffisance rénale sévère</span></li>\n        <li><strong>Effet secondaire :</strong> <span class=\"kw-clinique\">diarrhée</span> — 1ᵉʳ signe de toxicité, devant faire diminuer ou arrêter le traitement</li>\n        <li><strong>Interactions (via CYP P450) :</strong> <span class=\"kw-ci\">macrolides</span>, <span class=\"kw-ci\">ciclosporine</span>, <span class=\"kw-ci\">vérapamil</span>, <span class=\"kw-ci\">statines</span></li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-ttt\">biologique</span> :</strong> transaminases, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span></li>\n        <li><strong>Réduire les doses si :</strong> <span class=\"kw-clinique\">diarrhée</span> ; âge &gt;<span class=\"kw-chiffre\"> 70 ans</span> ; poids &lt;<span class=\"kw-chiffre\"> 70 kg</span> ; <span class=\"kw-ci\">insuffisance rénale</span> &lt;<span class=\"kw-chiffre\"> 35 mL</span>/min</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Suivi</span></h4>\n      <p>Consultations à <span class=\"kw-chiffre\">J7</span> (médecin traitant), <span class=\"kw-chiffre\">M1</span> (cardiologue + <span class=\"kw-imagerie\">ETT</span>), <span class=\"kw-chiffre\">M3</span> et <span class=\"kw-chiffre\">M6</span> — pour vérifier l'absence de symptômes, la normalisation de la <span class=\"kw-bio\">CRP</span> et de l'<span class=\"kw-imagerie\">ETT</span>.</p>\n      <div class=\"callout callout-info\"><strong>Place du <span class=\"kw-ttt\">drainage</span>.</strong> Drainage en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-alerte\">tamponnade</span> ; à discuter en cas de retentissement hémodynamique avec TA conservée, ou d'épanchement abondant chronique sans étiologie.</div>","frequence":1},{"id":"235-13","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Savoir énumérer les principales complications d’une péricardite aiguë","contenu":"<p>Les principales complications de la péricardite aiguë sont les suivantes.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Tamponnade</span></td><td>Complication la plus redoutable — <span class=\"kw-alerte\">urgence</span> vitale (compression des cavités droites, adiastolie aiguë)</td></tr>\n          <tr><td>Myocardite / myopéricardite</td><td>\n            Élévation de la <span class=\"kw-bio\">troponine</span> ± <span class=\"kw-bio\">CPK</span> (peut mimer un <span class=\"kw-def\">SCA</span>)<br>\n            <span class=\"kw-imagerie\">IRM</span> avec gadolinium = examen de choix : <span class=\"kw-imagerie\">réhaussement tardif sous-épicardique</span> épargnant le sous-endocarde<br>\n            Risque d'<span class=\"kw-def\">insuffisance cardiaque</span> et de troubles du rythme ventriculaire\n          </td></tr>\n          <tr><td>Péricardite chronique <span class=\"kw-clinique\">constrictive</span></td><td>\n            Complique <span class=\"kw-chiffre\">&lt; 10 %</span> des péricardites ; épaississement fibreux/fibrocalcaire → <span class=\"kw-def\">adiastolie chronique</span><br>\n            <span class=\"kw-def\">Insuffisance cardiaque</span> droite (signe de Kussmaul, <strong>absence</strong> de signe de Harzer)<br>\n            Cathétérisme : <span class=\"kw-def\">dip-plateau</span> + égalisation des pressions diastoliques ; traitement = péricardectomie\n          </td></tr>\n          <tr><td>Péricardite récidivante</td><td>\n            <strong>Complication la plus fréquente</strong> (<span class=\"kw-chiffre\">20-30 %</span>)<br>\n            Survient souvent après une durée de traitement insuffisante ; prévention par <span class=\"kw-ttt\">colchicine</span>\n          </td></tr>\n          <tr><td>Péricardite chronique</td><td><span class=\"kw-clinique\">Évolution</span> &gt;<span class=\"kw-chiffre\"> 3 mois</span> ; doit faire suspecter une cause <span class=\"kw-etio\">tuberculeuse</span> ou <span class=\"kw-etio\">néoplasique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Récidivante = la plus fréquente ; <span class=\"kw-alerte\">tamponnade</span> = la plus grave ; <span class=\"kw-clinique\">constrictive</span> = la plus tardive (séquelle fibreuse).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":2},{"id":"235-14","rang":"B","rubrique":"Etiologies","titre":"Savoir évoquer les principales étiologies devant une tamponnade","contenu":"<p>En théorie, <strong>toutes</strong> les péricardites peuvent se compliquer de <span class=\"kw-alerte\">tamponnade</span>. En pratique, certaines étiologies y exposent beaucoup plus.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Néoplasiques</span> <strong>+++</strong> (cause la plus fréquente de <span class=\"kw-alerte\">tamponnade</span>)</li>\n        <li><span class=\"kw-alerte\">Hémopéricarde</span> : <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span>, post-traumatique, post-chirurgicale, post-<span class=\"kw-ttt\">ponction</span></li>\n        <li><span class=\"kw-etio\">Tuberculeuse</span></li>\n        <li><span class=\"kw-etio\">Purulente</span></li>\n        <li><span class=\"kw-etio\">Virale</span> : se complique <strong>exceptionnellement</strong> de <span class=\"kw-alerte\">tamponnade</span> (diagnostic d'exclusion)</li>\n        <li><span class=\"kw-etio\">Urémique</span></li>\n        <li><span class=\"kw-def\">IDM</span> (notamment après <span class=\"kw-ttt\">thrombolyse</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant une <span class=\"kw-alerte\">tamponnade</span>, penser d'abord <span class=\"kw-etio\">néoplasie</span> et <span class=\"kw-alerte\">hémopéricarde</span> ; une origine <span class=\"kw-etio\">virale</span> pure est rare et reste un diagnostic d'élimination.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"235-15","rang":"A","rubrique":"Identification de l’urgence","titre":"Savoir faire le diagnostic d’une tamponnade","contenu":"<p>La <span class=\"kw-def\">tamponnade</span> est la compression des cavités droites par un <span class=\"kw-imagerie\">épanchement péricardique</span> abondant et/ou d'installation brutale. C'est une <strong><span class=\"kw-alerte\">urgence</span></strong> : risque d'arrêt cardio-circulatoire par adiastolie — complication la plus redoutable de la péricardite.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Le risque de <span class=\"kw-alerte\">tamponnade</span> dépend moins du volume de l'épanchement que de la <span class=\"kw-alerte\">rapidité de sa constitution</span> : pression intra-péricardique &gt; pressions intracavitaires → <span class=\"kw-def\">adiastolie aiguë</span> → chute du débit → <span class=\"kw-def\">choc cardiogénique</span>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Présentation clinique</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur thoracique</span> inconstante (pas de frottement si épanchement important)</li>\n        <li><span class=\"kw-clinique\">Dyspnée</span> positionnelle, <span class=\"kw-clinique\">polypnée</span> puis <span class=\"kw-clinique\">orthopnée</span>, <span class=\"kw-clinique\">toux</span></li>\n        <li>Signes d'<span class=\"kw-alerte\">insuffisance cardiaque droite</span> (<span class=\"kw-clinique\">turgescence jugulaire</span> sans <span class=\"kw-def\">OAP</span>)</li>\n        <li>Tableau de <span class=\"kw-alerte\">choc</span> : <span class=\"kw-clinique\">tachycardie</span>, PAS <span class=\"kw-chiffre\">&lt; 90 mmHg</span> réfractaire, marbrures, extrémités froides</li>\n        <li><span class=\"kw-alerte\">Pouls paradoxal</span> : chute de la PAS <span class=\"kw-chiffre\">&gt; 10 mmHg</span> à l'inspiration</li>\n        <li>Bruits du cœur assourdis, sans frottement</li>\n      </ul>\n      <p><strong>Diagnostics différentiels</strong> (<span class=\"kw-alerte\">choc</span> avec signes droits) : <span class=\"kw-etio\">infarctus du ventricule droit</span>, <span class=\"kw-def\">embolie pulmonaire</span> massive, <span class=\"kw-alerte\">tamponnade</span> gazeuse (<span class=\"kw-imagerie\">pneumothorax</span> compressif, <span class=\"kw-etio\">asthme aigu grave</span>).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Paraclinique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td>Signes de péricardite + <span class=\"kw-alerte\">microvoltage</span> (non spécifique) + <span class=\"kw-alerte\">alternance électrique</span> (inconstante mais spécifique)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">RXT</span></td><td><span class=\"kw-imagerie\">Cardiomégalie</span> « en carafe » ou « en sabot » ; peut être normale</td></tr>\n          <tr><td><span class=\"kw-imagerie\">ETT</span></td><td>Confirme le diagnostic : <span class=\"kw-imagerie\">swinging heart</span> ; collapsus du VD et de l'OD en expiration ; compression du VG en inspiration (septum paradoxal)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/235/tamponnade-rxt-ecg.png\" alt=\"Radiographie thoracique et ECG d'une tamponnade péricardique montrant une cardiomégalie en carafe et un microvoltage avec alternance électrique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-alerte\">Tamponnade</span> péricardique — <span class=\"kw-imagerie\">radiographie thoracique</span> (cardiomégalie « en carafe ») et <span class=\"kw-bio\">ECG</span> (microvoltage, alternance électrique). Source : fiche source EDN item 235.</figcaption>\n      </figure>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Prise en charge</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> en soins intensifs — <span class=\"kw-alerte\">urgence</span> médico-chirurgicale</li>\n        <li>Remplissage vasculaire (macromolécules ou soluté salé isotonique) ± amines vasoactives</li>\n        <li><strong><span class=\"kw-ttt\">Drainage</span> en <span class=\"kw-alerte\">urgence</span></strong> : <span class=\"kw-ttt\">ponction</span> péricardique écho-guidée ou <span class=\"kw-ttt\">drainage chirurgical</span></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pièges à ne pas commettre.</strong> Éviter l'<span class=\"kw-ci\">intubation orotrachéale</span> (aggrave la dysfonction droite, haut risque d'<span class=\"kw-alerte\">arrêt cardiaque</span>). La <span class=\"kw-ttt\">ponction</span> péricardique est <span class=\"kw-ci\">contre-indiquée de façon absolue</span> en cas de suspicion de <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Tamponnade</span> <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale médico-chirurgicale</span></strong></p><p><span class=\"kw-ttt\">Drainage péricardique en urgence</span> (<span class=\"kw-ttt\">ponction</span> écho-guidée ou <span class=\"kw-ttt\">drainage chirurgical</span>) + <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-ttt\">soins intensifs</span></p><ul><li>Compression des cavités droites → <span class=\"kw-def\">adiastolie aiguë</span> → <span class=\"kw-alerte\">choc cardiogénique</span></li><li>Risque d'<span class=\"kw-alerte\">arrêt cardio-circulatoire par adiastolie</span> — appel en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Myo-péricardite <span class=\"q\">— <span class=\"kw-bio\">troponine</span> élevée</span></strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> avec <span class=\"kw-bio\">scope</span> ; <span class=\"kw-imagerie\">IRM cardiaque</span> (réhaussement tardif sous-épicardique)</p><ul><li>Élévation de la <span class=\"kw-bio\">troponine</span> ± <span class=\"kw-bio\">CPK</span> (peut mimer un <span class=\"kw-def\">SCA</span>)</li><li>Risque de <span class=\"kw-alerte\">troubles du rythme ventriculaire</span> et d'<span class=\"kw-def\">insuffisance cardiaque</span></li></ul><p><strong>Épanchement abondant persistant</strong></p><p><span class=\"kw-ttt\">Ponction péricardique</span> (évacuatrice + analyse du liquide)</p><ul><li>Épanchement abondant et <span class=\"kw-clinique\">symptomatique</span> malgré un traitement médical bien conduit depuis <span class=\"kw-chiffre\">1 semaine</span></li></ul>","hospit":"<p><span class=\"kw-alerte\">Hospitalisation</span> <strong>non systématique</strong> (PEC ambulatoire dans &gt;<span class=\"kw-chiffre\"> 80 %</span> des cas) ; elle s'impose en présence d'<span class=\"kw-chiffre\">≥ 1 facteur majeur</span> ou d'un faisceau de facteurs mineurs (risque de complication / étiologie non bénigne).</p><p><strong>Facteurs prédictifs majeurs</strong></p><ul><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">&gt; 38 °C</span></li><li>Début <span class=\"kw-clinique\">subaigu</span> (symptômes depuis plusieurs jours/semaines)</li><li>Épanchement <span class=\"kw-imagerie\">abondant</span> (<span class=\"kw-chiffre\">&gt; 20 mm</span>) ou <span class=\"kw-alerte\">tamponnade</span></li><li><span class=\"kw-alerte\">Résistance</span> au traitement anti-<span class=\"kw-etio\">inflammatoire</span> depuis <span class=\"kw-chiffre\">&gt; 7 jours</span></li></ul><p><strong>Facteurs prédictifs mineurs</strong></p><ul><li>Patient <span class=\"kw-etio\">immunodéprimé</span></li><li>Patient sous <span class=\"kw-ttt\">anticoagulant</span></li><li>Suites d'un <span class=\"kw-etio\">traumatisme thoracique</span></li><li><span class=\"kw-alerte\">Myocardite</span> associée (<span class=\"kw-bio\">troponines</span> élevées)</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Signes de choc</span> (PAS &lt;<span class=\"kw-chiffre\"> 90 mmHg</span>, marbrures, extrémités froides)</li><li><span class=\"kw-alerte\">Insuffisance cardiaque droite</span> (<span class=\"kw-clinique\">turgescence jugulaire</span>) — jamais banale dans une péricardite</li><li><span class=\"kw-alerte\">Pouls paradoxal</span> (chute de la PAS <span class=\"kw-chiffre\">&gt; 10 mmHg</span> à l'inspiration)</li><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">&gt; 38 °C</span></li><li>Élévation de la <span class=\"kw-bio\">troponine</span> (myocardite associée)</li><li><span class=\"kw-alerte\">Microvoltage</span> et <span class=\"kw-alerte\">alternance électrique</span> à l'<span class=\"kw-bio\">ECG</span> (<span class=\"kw-alerte\">tamponnade</span>)</li><li>Épanchement <span class=\"kw-chiffre\">&gt; 20 mm</span> comprimant les cavités droites à l'<span class=\"kw-imagerie\">ETT</span></li></ul>","principes":"<p>Péricardite bénigne = <strong>bithérapie anti-<span class=\"kw-etio\">inflammatoire</span> prolongée</strong> (<span class=\"kw-ttt\">AINS</span> + <span class=\"kw-ttt\">colchicine</span>) en ambulatoire ; <span class=\"kw-ci\">pas de corticoïdes en 1ʳᵉ intention</span> (favorisent les récidives).</p><p><strong>Mesures générales</strong></p><ul><li><span class=\"kw-clinique\">Repos</span> jusqu'à disparition des symptômes et normalisation des examens (<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">ETT</span>)</li><li>Arrêt de travail ; traitement de la <span class=\"kw-clinique\">douleur thoracique</span></li><li><span class=\"kw-ttt\">Protecteur gastrique</span> en cas de bithérapie anti-<span class=\"kw-etio\">inflammatoire</span></li></ul><p><strong><span class=\"kw-ttt\">AINS</span> <span class=\"q\">— traitement d'attaque</span></strong></p><ul><li><span class=\"kw-ttt\">Ibuprofène</span> <span class=\"kw-chiffre\">600–800 mg ×3/j</span> ou <span class=\"kw-ttt\">aspirine</span> <span class=\"kw-chiffre\">750–1000 mg ×3/j</span> pendant <span class=\"kw-chiffre\">1 à 2 semaines</span></li><li>Arrêt progressif selon symptômes, <span class=\"kw-bio\">CRP</span> et <span class=\"kw-imagerie\">ETT</span> — durée totale <span class=\"kw-chiffre\">4 à 8 semaines</span></li></ul><p><strong>Colchicine</strong></p><p>Interactions via CYP P450 : <span class=\"kw-ci\">macrolides</span>, <span class=\"kw-ci\">ciclosporine</span>, <span class=\"kw-ci\">vérapamil</span>, <span class=\"kw-ci\">statines</span></p><ul><li><span class=\"kw-ttt\">Colchicine</span> <span class=\"kw-chiffre\">0,5 mg ×1/j</span> (&lt;<span class=\"kw-chiffre\"> 70 kg</span>) ou <span class=\"kw-chiffre\">×2/j</span> (&gt;<span class=\"kw-chiffre\"> 70 kg</span>) pendant <span class=\"kw-chiffre\">3 mois</span></li><li>Réduit le risque de récidive de <span class=\"kw-chiffre\">50 %</span> ; <span class=\"kw-ci\">CI : insuffisance rénale sévère</span> ; 1ᵉʳ signe de toxicité = <span class=\"kw-clinique\">diarrhée</span></li></ul><p><strong><span class=\"kw-ttt\">Corticoïdes</span> <span class=\"q\">— 2ᵉ intention seulement</span></strong></p><p><span class=\"kw-ci\">Jamais en 1ʳᵉ intention</span> — favorisent les récidives</p><ul><li><span class=\"kw-ttt\">Corticoïdes</span> <span class=\"kw-chiffre\">0,25–0,5 mg/kg/j</span>, en association, <strong>uniquement en cas d'échec</strong></li></ul><p><strong>Place du <span class=\"kw-ttt\">drainage</span></strong></p><ul><li><span class=\"kw-ttt\">Drainage en urgence</span> si <span class=\"kw-alerte\">tamponnade</span></li><li>À discuter si retentissement hémodynamique avec TA conservée, ou épanchement abondant chronique sans étiologie</li></ul>","suivi":"<p><strong>Calendrier :</strong> <span class=\"kw-chiffre\">J7</span> (médecin traitant), <span class=\"kw-chiffre\">M1</span> (cardiologue + <span class=\"kw-imagerie\">ETT</span>), <span class=\"kw-chiffre\">M3</span> et <span class=\"kw-chiffre\">M6</span>.<br><strong>Objectifs :</strong> absence de symptômes, normalisation de la <span class=\"kw-bio\">CRP</span> et de l'<span class=\"kw-imagerie\">ETT</span>, gestion de l'arrêt progressif du traitement.<br><strong>Colchicine :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-ttt\">biologique</span> (transaminases, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">NFS-plaquettes</span>) ; réduire les doses si <span class=\"kw-clinique\">diarrhée</span>, âge &gt;<span class=\"kw-chiffre\"> 70 ans</span>, poids &lt;<span class=\"kw-chiffre\"> 70 kg</span> ou IR &lt;<span class=\"kw-chiffre\"> 35 mL</span>/min.<br><strong>Complications à dépister :</strong> <span class=\"kw-alerte\">récidive</span> (la plus fréquente, <span class=\"kw-chiffre\">20–30 %</span>), <span class=\"kw-alerte\">tamponnade</span> (la plus grave), <span class=\"kw-def\">péricardite chronique constrictive</span> (la plus tardive).</p>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-20-item-235-pericardite-aigue","label":"SFC — Chapitre 20 item 235 pericardite aigue"},{"href":"https://www.e-cardiogram.com/pericardite-aigue-1-typique/","label":"Pericardite aigue 1 typique"},{"href":"https://ecgclic.fr/wp-content/uploads/2017/11/Pericardite.pdf","label":"Pericardite"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Péricardite aiguë : signes de gravité / tamponnade ? — Diagnostic retenu (≥ 2/4 critères) — premier tri sur le retentissement hémodynamique","detail":"<h4>CAT — péricardite aiguë : gravité et orientation — Tri sur la <span class=\"kw-alerte\">tamponnade</span>, puis les facteurs de gravité / d'<span class=\"kw-alerte\">hospitalisation</span></h4>","branches":[{"to":"t-tamponnade","label":"Tamponnade : choc + signes droits + épanchement compressif","color":"red"},{"to":"q-gravite","label":"Pas de tamponnade","color":"blue"}]},{"id":"t-tamponnade","kind":"terminal","label":"Tamponnade — drainage en urgence","color":"red","detail":"<h4>Diagnostic (<span class=\"kw-imagerie\">ETT</span> +++)</h4><ul><li><span class=\"kw-imagerie\">ETT</span> : <span class=\"kw-imagerie\">swinging heart</span>, collapsus du VD et de l'OD en expiration, compression du VG en inspiration</li><li><span class=\"kw-bio\">ECG</span> : <span class=\"kw-alerte\">microvoltage</span> + <span class=\"kw-alerte\">alternance électrique</span></li><li><span class=\"kw-imagerie\">RXT</span> : cardiomégalie « en carafe » (peut être normale)</li></ul><h4>Conduite — <span class=\"kw-alerte\">urgence</span> médico-chirurgicale</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-ttt\">soins intensifs</span></li><li><span class=\"kw-ttt\">Remplissage vasculaire</span> (macromolécules ou sérum salé isotonique) ± <span class=\"kw-ttt\">amines vasoactives</span></li><li><span class=\"kw-ttt\">Drainage en urgence</span> : <span class=\"kw-ttt\">ponction</span> péricardique écho-guidée ou <span class=\"kw-ttt\">drainage chirurgical</span></li></ul><h4>Pièges <span class=\"kw-ci\">à éviter</span></h4><ul><li><span class=\"kw-ci\">Intubation orotrachéale</span> (aggrave la dysfonction droite, risque d'<span class=\"kw-alerte\">arrêt cardiaque</span>)</li><li><span class=\"kw-ttt\">Ponction</span> <span class=\"kw-ci\">contre-indiquée de façon absolue</span> si suspicion de <span class=\"kw-etio\">dissection aortique</span></li></ul><h4>Renvoi</h4><ul><li>Item 332 (Etat de <span class=\"kw-alerte\">choc</span>)</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Facteur de gravité ou d'hospitalisation ? — Fièvre, début subaigu, épanchement abondant, résistance au traitement, immunodépression, anticoagulant, traumatisme, troponine","branches":[{"to":"q-tropo","label":"≥ 1 facteur présent","color":"amber"},{"to":"t-ambu","label":"Aucun facteur — forme bénigne","color":"green"}]},{"id":"q-tropo","kind":"decision","label":"Élévation de la troponine (myocardite associée) ? — Troponine ± CPK — peut mimer un SCA","branches":[{"to":"t-myoperic","label":"Oui","color":"red"},{"to":"t-hospit","label":"Non","color":"amber"}]},{"id":"t-myoperic","kind":"terminal","label":"Myo-péricardite","color":"red","detail":"<h4>Confirmation</h4><ul><li>Élévation de la <span class=\"kw-bio\">troponine</span> ± <span class=\"kw-bio\">CPK</span> (peut mimer un <span class=\"kw-def\">SCA</span>)</li><li><span class=\"kw-imagerie\">IRM cardiaque</span> avec gadolinium : <span class=\"kw-imagerie\">réhaussement tardif sous-épicardique</span> épargnant le sous-endocarde</li></ul><h4>Risques</h4><ul><li><span class=\"kw-alerte\">Troubles du rythme ventriculaire</span> et <span class=\"kw-def\">insuffisance cardiaque</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> avec <span class=\"kw-bio\">scope</span> (<span class=\"kw-def\">surveillance</span> rythmique)</li><li><span class=\"kw-clinique\">Repos</span> ; traitement anti-<span class=\"kw-etio\">inflammatoire</span></li></ul><h4>Renvoi</h4><ul><li>Item 339 (<span class=\"kw-clinique\">Syndrome coronarien</span> aigu) · Item 234 (<span class=\"kw-ci\">Insuffisance cardiaque</span>)</li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation + bilan étiologique","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-chiffre\">≥ 1 facteur</span> de gravité / d'<span class=\"kw-alerte\">hospitalisation</span>, sans <span class=\"kw-alerte\">tamponnade</span> ni myocardite</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">créatininémie</span> avant <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">colchicine</span>)</li><li>Recherche d'une étiologie non bénigne : <span class=\"kw-etio\">purulente</span>, <span class=\"kw-etio\">tuberculeuse</span>, <span class=\"kw-etio\">néoplasique</span>, <span class=\"kw-etio\">maladie systémique</span></li><li><span class=\"kw-ttt\">Ponction péricardique</span> si épanchement abondant symptomatique persistant (&gt; <span class=\"kw-chiffre\">1 semaine</span>)</li></ul><h4>Traitement</h4><ul><li>Bithérapie anti-<span class=\"kw-etio\">inflammatoire</span> : <span class=\"kw-ttt\">AINS</span> + <span class=\"kw-ttt\">colchicine</span></li></ul><h4>Renvoi</h4><ul><li>Item 159 (<span class=\"kw-etio\">Tuberculose</span>) · Item 169 (<span class=\"kw-etio\">VIH</span>)</li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Péricardite bénigne — ambulatoire","color":"green","detail":"<h4>Profil</h4><ul><li>Sujet <span class=\"kw-clinique\">jeune</span>, forme <span class=\"kw-etio\">virale / idiopathique</span> typique, sans facteur de gravité</li></ul><h4>Traitement ambulatoire</h4><ul><li><span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">ibuprofène</span> ou <span class=\"kw-ttt\">aspirine</span>) <span class=\"kw-chiffre\">1 à 2 semaines</span>, arrêt progressif sur <span class=\"kw-chiffre\">4 à 8 semaines</span></li><li><span class=\"kw-ttt\">Colchicine</span> <span class=\"kw-chiffre\">0,5 mg ×1-2/j</span> pendant <span class=\"kw-chiffre\">3 mois</span> (réduit les récidives de <span class=\"kw-chiffre\">50 %</span>)</li><li><span class=\"kw-ttt\">Protecteur gastrique</span> ; <span class=\"kw-clinique\">repos</span> ; arrêt de travail</li></ul><h4>À ne pas faire</h4><ul><li><span class=\"kw-ci\">Corticoïdes en 1ʳᵉ intention</span> (favorisent les récidives)</li><li><span class=\"kw-ci\">Recherches virologiques</span> dans une forme typique (inutiles)</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Consultations <span class=\"kw-chiffre\">J7</span>, <span class=\"kw-chiffre\">M1</span> (cardiologue + <span class=\"kw-imagerie\">ETT</span>), <span class=\"kw-chiffre\">M3</span>, <span class=\"kw-chiffre\">M6</span></li></ul>"}]},"cards":[{"i":"2f8f2f1f5af6","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Quand parle-t-on de myopéricardite lors d'une péricardite aiguë ?","a":"<p>On parle de <strong>myopéricardite</strong> lorsqu'une péricardite aiguë est associée à une <strong>élévation de la troponine</strong> (signe d'une atteinte myocardique associée). Il ne faut pas la confondre avec un syndrome coronarien aigu.</p>"},{"i":"615225b2660d","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Comment qualifie-t-on une péricardite aiguë sans épanchement péricardique ?","a":"<p>Une péricardite aiguë sans épanchement péricardique est appelée <strong>« péricardite sèche »</strong>.</p>"},{"i":"e26c1c8b3ec5","n":235,"o":"235-1","u":"Définition","t":"Connaître la définition d’une péricardite aiguë","q":"Quelle est la définition d'une péricardite aiguë ?","a":"<p>La péricardite aiguë est définie comme une <strong>inflammation aiguë des feuillets péricardiques</strong> (viscéral et pariétal).</p>"},{"i":"3cb99f4540e4","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quand et pour quelles raisons un drainage péricardique peut-il être indiqué dans la péricardite aiguë ?","a":"<p>Le drainage péricardique est indiqué :</p><ul><li>En urgence en cas de <strong>tamponnade cardiaque</strong>.</li><li>Il est à discuter en cas de <strong>retentissement hémodynamique avec TA conservée</strong>, ou d'<strong>épanchement abondant chronique</strong> sans étiologie identifiée.</li></ul>"},{"i":"6ade299588a7","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quelle est la stratégie médicamenteuse de première intention pour traiter une péricardite aiguë bénigne ?","a":"<p>La stratégie médicamenteuse de première intention repose sur une <strong>bithérapie anti-inflammatoire prolongée</strong> :</p><ul><li><strong>AINS</strong> (ibuprofène 600-800 mg ×3/j ou aspirine 750-1000 mg ×3/j) en phase d'attaque pendant <strong>1 à 2 semaines</strong>, puis arrêt progressif sur <strong>4 à 8 semaines</strong> selon les symptômes, la CRP et l'ETT.</li><li><strong>Colchicine</strong> 0,5 mg ×1/j (poids < 70 kg) ou ×2/j (poids > 70 kg) pendant <strong>3 mois</strong>. Elle diminue la douleur, la durée des symptômes et réduit le risque de récidive de 50 %.</li></ul>"},{"i":"b7853c506192","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quels sont les éléments importants à connaître concernant la colchicine dans le cadre d'une péricardite aiguë bénigne ?","a":"<p>Concernant la colchicine :</p><ul><li>Sa principale contre-indication est l'<strong>insuffisance rénale sévère</strong>.</li><li>L'effet secondaire le plus fréquent est la <strong>diarrhée</strong>, qui est le 1<sup>er</sup> signe de toxicité et doit faire diminuer ou arrêter le traitement.</li><li>Des interactions sont possibles (via CYP P450) avec les <strong>macrolides</strong>, la <strong>ciclosporine</strong>, le <strong>vérapamil</strong> et les <strong>statines</strong>.</li><li>La surveillance biologique inclut les <strong>transaminases, la créatinine, les CPK et la NFS-plaquettes</strong>.</li><li>Les doses doivent être réduites si diarrhée, âge > 70 ans, poids < 70 kg ou insuffisance rénale < 35 mL/min.</li></ul>"},{"i":"d111fa2b860d","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Dans quel contexte et selon quelles modalités peut-on envisager les corticoïdes dans le traitement de la péricardite aiguë bénigne ?","a":"<p>Les corticoïdes (0,25-0,5 mg/kg/j) sont utilisés <strong>uniquement en 2<sup>e</sup> intention</strong> et en association, en cas d'<strong>échec des AINS et de la colchicine</strong>. Il s'agit d'un <strong>piège classique</strong> : ils ne doivent pas être utilisés en 1<sup>re</sup> intention dans la péricardite aiguë bénigne car ils favorisent les récidives.</p>"},{"i":"ee97e014fce4","n":235,"o":"235-12","u":"Prise en charge","t":"Connaître le traitement d’une péricardite aiguë bénigne","q":"Quelles sont les mesures générales recommandées pour la prise en charge d'une péricardite aiguë bénigne ?","a":"<p>Les mesures générales comprennent :</p><ul><li>Un <strong>repos</strong> jusqu'à la disparition des symptômes et la normalisation des examens (CRP, ECG, ETT), en général pendant le premier mois.</li><li>Un <strong>arrêt de travail</strong>.</li><li>Un traitement de la <strong>douleur thoracique</strong>.</li><li>Un <strong>protecteur gastrique</strong> si une bithérapie anti-inflammatoire est associée.</li></ul>"},{"i":"0b3eeb457217","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Qu'est-ce que la péricardite chronique constrictive, complication de la péricardite aiguë, et comment est posé son diagnostic ?","a":"<p>La péricardite chronique constrictive est une complication d'une péricardite aiguë qui survient dans <strong>moins de 10%</strong> des cas. Elle est due à un <strong>épaississement fibreux ou fibrocalcaire du péricarde</strong> entraînant une <strong>adiastolie chronique</strong>, et se manifeste par une <strong>insuffisance cardiaque droite</strong> (avec signe de Kussmaul et absence de signe de Harzer). Le diagnostic est évoqué par le cathétérisme cardiaque montrant un <strong>pattern « dip-plateau »</strong> et une <strong>égalisation des pressions diastoliques</strong>. Le traitement est la péricardectomie.</p>"},{"i":"446f4918f618","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Comment la myocardite ou myopéricardite, complication de la péricardite aiguë, est-elle caractérisée et quel est son examen de choix ?","a":"<p>La myocardite/myopéricardite se caractérise par une <strong>élévation de la troponine</strong> (± CPK), pouvant mimer un SCA. L'examen de choix est l'<strong>IRM cardiaque avec injection de gadolinium</strong>, montrant un rehaussement tardif sous-épicardique épargnant le sous-endocarde. Ses risques sont l'insuffisance cardiaque et les troubles du rythme ventriculaire.</p>"},{"i":"48dfde0e3284","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quand suspecter une péricardite chronique et à quelles étiologies spécifiques doit-elle faire penser ?","a":"<p>On parle de péricardite chronique lorsqu'elle évolue depuis <strong>plus de 3 mois</strong>. Elle doit faire suspecter une étiologie <strong>tuberculeuse ou néoplasique</strong>.</p>"},{"i":"70c88b0690ae","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quelle est la complication la plus fréquente de la péricardite aiguë et comment peut-elle être prévenue ?","a":"<p>La complication la plus fréquente de la péricardite aiguë est la <strong>péricardite récidivante</strong>, survenant dans <strong>20 à 30% des cas</strong>. Elle survient souvent après une durée de traitement insuffisante. Sa prévention repose sur la <strong>colchicine</strong>.</p>"},{"i":"cb194de87c63","n":235,"o":"235-13","u":"Suivi et/ou pronostic","t":"Savoir énumérer les principales complications d’une péricardite aiguë","q":"Quelle est la complication la plus redoutable de la péricardite aiguë et ses caractéristiques ?","a":"<p>La complication la plus redoutable de la péricardite aiguë est la <strong>tamponnade</strong>. C'est une urgence vitale caractérisée par une compression des cavités cardiaques droites, entraînant une <strong>adiastolie aiguë</strong>.</p>"},{"i":"2a6bdb6859f2","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les éléments paracliniques permettant de confirmer le diagnostic de tamponnade ?","a":"<ul><li><strong>Échographie transthoracique (ETT)</strong> : elle confirme le diagnostic en montrant un <strong>« swinging heart »</strong> (cœur se balançant dans l'épanchement), un <strong>collapsus du ventricule droit (VD) et de l'oreillette droite (OD) en expiration</strong>, et une compression du ventricule gauche (VG) en inspiration (septum paradoxal).</li><li><strong>Électrocardiogramme (ECG)</strong> : signes de péricardite aigüe associés à un <strong>microvoltage</strong> (non spécifique) et une <strong>alternance électrique</strong> (inconstante mais spécifique).</li><li><strong>Radiographie thoracique (RXT)</strong> : peut montrer une cardiomégalie « en carafe » ou « en sabot », mais peut aussi être normale.</li></ul>"},{"i":"415b0020fd50","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les signes cliniques clés d'une tamponnade cardiaque ?","a":"<ul><li><strong>Dyspnée positionnelle</strong>, polypnée puis orthopnée, toux.</li><li>Signes d'<strong>insuffisance cardiaque droite</strong> : <strong>turgescence jugulaire</strong> sans œdème aigu du poumon (OAP).</li><li>Tableau de <strong>choc</strong> : <strong>tachycardie</strong>, pression artérielle systolique (PAS) inférieure à 90 mmHg réfractaire, marbrures, extrémités froides.</li><li><strong>Pouls paradoxal</strong> : chute de la PAS de <strong>plus de 10 mmHg à l'inspiration</strong>.</li><li>Bruits du cœur assourdis, sans frottement péricardique (si épanchement important).</li><li>La douleur thoracique est inconstante.</li></ul>"},{"i":"54446a0e4e3d","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les principes de prise en charge d'une tamponnade cardiaque ?","a":"<ul><li><strong>Hospitalisation en soins intensifs</strong>.</li><li><strong>Remplissage vasculaire</strong> (macromolécules ou soluté salé isotonique) et, si besoin, amines vasoactives.</li><li><strong>Drainage en urgence</strong> : ponction péricardique <strong>écho-guidée</strong> ou drainage chirurgical.</li></ul>"},{"i":"678876058ad1","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quelle est la définition de la tamponnade cardiaque ?","a":"<p>La tamponnade cardiaque est la <strong>compression des cavités droites</strong> du cœur par un épanchement péricardique, qu'il soit abondant et/ou d'installation brutale. C'est une urgence vitale, car elle risque d'entraîner un <strong>arrêt cardio-circulatoire par adiastolie</strong>.</p>"},{"i":"ad93cc4cb4fc","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Comment interpréter la physiopathologie de la tamponnade cardiaque ?","a":"<p>Le risque de tamponnade dépend moins du volume de l'épanchement que de la <strong>rapidité de sa constitution</strong>. Une pression intra-péricardique supérieure aux pressions intracavitaires entraîne une <strong>adiastolie aiguë</strong>, une chute brutale du débit cardiaque et un <strong>choc cardiogénique</strong>.</p>"},{"i":"f860339fa646","n":235,"o":"235-15","u":"Identification de l’urgence","t":"Savoir faire le diagnostic d’une tamponnade","q":"Quels sont les pièges à éviter dans la prise en charge d'une tamponnade cardiaque ?","a":"<ul><li><strong>Éviter l'intubation orotrachéale</strong>, car elle peut aggraver la dysfonction cardiaque droite et augmenter le risque d'arrêt cardiaque.</li><li>La ponction péricardique est <strong>contre-indiquée de façon absolue en cas de suspicion de dissection aortique</strong>.</li></ul>"},{"i":"12760eced371","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quelles sont les caractéristiques de la douleur thoracique d'une péricardite aiguë ?","a":"<p>La douleur thoracique péricarditique présente les caractéristiques suivantes :</p><ul><li><strong>Localisation</strong> : Rétrosternale ou précordiale gauche.</li><li><strong>Durée</strong> : Prolongée, permanente.</li><li><strong>Majorée par</strong> : Le décubitus, l'inspiration profonde, la toux (douleur impulsive).</li><li><strong>Calmée par</strong> : La position <strong>assise penchée en avant</strong> (antéflexion), appelée « prière mahométane ».</li><li><strong>Signes négatifs</strong> : Elle est résistante à la trinitrine et ne survient pas à l'effort.</li></ul>"},{"i":"159b8e0b5edc","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quels sont les autres signes et symptômes cliniques fréquemment associés à la péricardite aiguë ?","a":"<p>Outre la douleur thoracique et le frottement péricardique, les signes et symptômes associés à la péricardite aiguë peuvent inclure :</p><ul><li>Une <strong>fièvre modérée</strong> (présente d'emblée, moins fréquente chez le sujet âgé).</li><li>Un <strong>syndrome grippal</strong> (myalgies, asthénie) précédant la péricardite de quelques jours.</li><li>Parfois une <strong>dyspnée</strong> (également soulagée par l'antéflexion), une toux sèche ou un hoquet.</li><li>Un <strong>frottement péricardique</strong> dont la particularité est d'être précoce, inconstant et fugace, de sonorité râpeuse (comparable à un « crissement de cuir neuf »). Il est systolodiastolique.</li><li>Une <strong>tachycardie</strong> souvent présente.</li><li>Des signes d'<strong>épanchement pleural associé</strong> possibles : disparition du murmure vésiculaire, matité à la percussion.</li></ul>"},{"i":"7443f9c3f0fb","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quels sont les critères diagnostiques essentiels d'une péricardite aiguë selon les recommandations EDN ?","a":"<p>Le diagnostic de péricardite aiguë est retenu si au moins <strong>2 des 4 critères</strong> suivants sont présents :</p><ul><li>Une <strong>douleur thoracique</strong> d'allure péricarditique.</li><li>Un <strong>frottement péricardique</strong> à l'auscultation.</li><li>Des anomalies <strong>ECG typiques</strong> (stade 1 ou sous-décalage de l'intervalle PQ).</li><li>Un <strong>épanchement péricardique</strong> (visibles à l'échographie transthoracique).</li></ul>"},{"i":"903455fe2630","n":235,"o":"235-2","u":"Diagnostic positif","t":"Connaître les symptômes et les signes cliniques d’une péricardite aiguë","q":"Quel signe clinique doit alerter sur une complication grave en cas de péricardite aiguë ?","a":"<p>La présence de <strong>signes d'insuffisance cardiaque droite</strong> doit faire suspecter une <strong>tamponnade</strong>. Ce n'est jamais un signe bénin dans le contexte d'une péricardite aiguë.</p>"},{"i":"2c22028859e8","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quel signe biologique est en faveur d'une myocardite associée à la péricardite aiguë ?","a":"<p>L'<strong>élévation de la troponine</strong> est un signe biologique en faveur d'une myocardite associée à la péricardite aiguë.</p>"},{"i":"8a43938011d0","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes cliniques de gravité permettant de suspecter une tamponnade ou une myocardite associée dans le cadre d'une péricardite aiguë ?","a":"<p>Les signes cliniques de gravité d'une péricardite aiguë sont :</p><ul><li>Signes de <strong>choc</strong>.</li><li>Signes d'<strong>insuffisance cardiaque droite</strong>.</li><li><strong>Pouls paradoxal</strong> (signe évocateur de tamponnade).</li><li><strong>Fièvre > 38 °C</strong>.</li></ul>"},{"i":"cc81b6ad457e","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes échocardiographiques de gravité d'une péricardite aiguë, en particulier ceux évoquant une tamponnade ?","a":"<p>Les signes échocardiographiques (ETT) de gravité d'une péricardite aiguë sont :</p><ul><li>Un <strong>épanchement péricardique > 20 mm</strong>.</li><li>Une <strong>compression des cavités droites</strong>, ce qui est un signe direct de tamponnade.</p></li></ul>"},{"i":"d0fd865e5fb7","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quels sont les signes ECG de gravité d'une péricardite aiguë ?","a":"<p>Les signes ECG de gravité d'une péricardite aiguë sont :</p><ul><li><strong>Microvoltage</strong> et <strong>alternance électrique</strong>, qui sont des signes de tamponnade.</li><li>Troubles du <strong>rythme ventriculaire</strong>, qui orientent vers une myocardite associée.</li></ul>"},{"i":"e01453c5dd20","n":235,"o":"235-3","u":"Identification de l’urgence","t":"Connaître les signes de gravité d’une péricardite aiguë et savoir appeler en urgence pour un drainage de l’épanchement","q":"Quelle est l'attitude à adopter en cas de tamponnade cardiaque par épanchement péricardique ?","a":"<p>En présence d'une <strong>tamponnade cardiaque</strong> (épanchement abondant comprimant les cavités droites, avec retentissement hémodynamique), il faut <strong>appeler en urgence pour un drainage de l'épanchement péricardique</strong>. Le pronostic vital est engagé en raison du risque d'arrêt cardio-circulatoire par adiastolie.</p>"},{"i":"bfb7b49e7e83","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Comment évolue typiquement le sus-décalage du segment ST à l'ECG au cours des différents stades d'une péricardite aiguë ?","a":"<p>L'évolution typique du sus-décalage du segment ST en cas de péricardite aiguë peut être décrite en plusieurs stades :</p><ul><li><strong>Stade 1 (1ᵉʳ jour)</strong> : Sus-décalage ST concave vers le haut avec ondes T positives.</li><li><strong>Stade 2 (24-48 h)</strong> : Normalisation du segment ST et ondes T plates.</li><li><strong>Stade 3 (1ʳᵉ semaine)</strong> : Ondes T négatives.</li><li><strong>Stade 4 (1ᵉʳ mois)</strong> : Normalisation de l'ECG.</li></ul>"},{"i":"df71fdd02fd6","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quels signes électrocardiographiques spécifiques doit-on rechercher en cas d'épanchement péricardique abondant lors d'une péricardite aiguë ?","a":"<p>En cas d'épanchement péricardique abondant, l'ECG peut montrer :</p><ul><li>Un <strong>microvoltage diffus</strong> (QRS &lt; 5 mm en dérivations périphériques, &lt; 10 mm en précordiales).</li><li>Une <strong>alternance électrique</strong> (amplitude des QRS variable d'un battement à l'autre), équivalent du <em>swinging heart</em> à l'échographie.</li></ul>"},{"i":"f01954c16c25","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quelles sont les anomalies électrocardiographiques précoces pouvant être observées lors d'une péricardite aiguë ?","a":"<p>Lors d'une péricardite aiguë, les anomalies ECG précoces incluent :</p><ul><li>Une <strong>tachycardie sinusale</strong>.</li><li>Un <strong>sous-décalage du segment PQ</strong> (témoin d'une repolarisation atriale et d'une inflammation auriculaire).</li><li>Un <strong>sus-décalage du segment ST concave vers le haut</strong>, souvent diffus et non systématisé.</li></ul>"},{"i":"f056a6e058a7","n":235,"o":"235-4","u":"Examens complémentaires","t":"Connaître les modalités d’interprétation de l’ECG et du bilan biologique initial","q":"Quels sont les examens biologiques initiaux essentiels à réaliser lors de la prise en charge d'une péricardite aiguë et leur objectif ?","a":"<p>Le bilan biologique initial d'une péricardite aiguë comprend :</p><ul><li><strong>NFS, VS, CRP</strong> : pour rechercher un syndrome inflammatoire.</li><li><strong>Créatininémie, urée, ionogramme sanguin</strong> : pour évaluer la fonction rénale avant la prescription d'AINS ou de colchicine.</li><li><strong>Troponines I ou T ultra-sensibles, CPK</strong> : marqueurs de nécrose myocardique, dont l'élévation évoque une myocardite associée.</li><li><strong>Hémocultures</strong> : à réaliser en cas de fièvre, pour rechercher une étiologie infectieuse.</li></ul>"},{"i":"5ad7e07a3e6a","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quelles anomalies ECG sont caractéristiques et précoces d'une péricardite aiguë ?","a":"<p>L'ECG d'une péricardite aiguë présente généralement :</p><ul><li>Un <strong>sus-décalage du segment ST concave vers le haut</strong>, diffus (non systématisé), sans image en miroir.</li><li>Un <strong>sous-décalage du segment PQ</strong> (quasi pathognomonique).</li><li>Des <strong>ondes T positives</strong> (au stade 1).</li></ul>"},{"i":"661368c049ed","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quelle est la principale distinction ECG entre une péricardite aiguë et un syndrome coronaire aigu (SCA) ?","a":"<p>La principale distinction réside dans la morphologie et la distribution du sus-décalage ST :</p><ul><li>Dans la <strong>péricardite aiguë</strong> : sus-décalage <strong>diffus</strong>, <strong>concave vers le haut</strong>, <strong>sans image en miroir</strong>.</li><li>Dans le <strong>syndrome coronaire aigu (SCA)</strong> : sus-décalage <strong>systématisé</strong>, souvent <strong>convexe</strong>, et <strong>avec image en miroir</strong>.</li></ul>"},{"i":"b36ea586543e","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Quels signes ECG spécifiques peut-on observer en cas d'épanchement péricardique abondant lors d'une péricardite aiguë ?","a":"<p>En cas d'épanchement péricardique abondant, l'ECG peut montrer un <strong>microvoltage diffus</strong> et une <strong>alternance électrique</strong>, qui est l'équivalent électrique d'un <em>swinging heart</em>.</p>"},{"i":"ed3d596f3181","n":235,"o":"235-7","u":"Contenu multimédia","t":"Electrocardiogramme (ECG) d’une péricardite aiguë","q":"Comment évoluent les anomalies ECG d'une péricardite aiguë au cours des 4 stades décrits par la tétrade de Holtzman ?","a":"<p>L'évolution des anomalies ECG d'une péricardite aiguë suit 4 stades :</p><ul><li><strong>Stade 1</strong> (1er jour) : <strong>sus-décalage ST concave vers le haut</strong> et <strong>ondes T positives</strong>.</li><li><strong>Stade 2</strong> (24-48 h) : <strong>normalisation du ST</strong> et <strong>ondes T plates</strong>.</li><li><strong>Stade 3</strong> (1ère semaine) : apparition d'<strong>ondes T négatives</strong>.</li><li><strong>Stade 4</strong> (1er mois) : <strong>normalisation complète de l'ECG</strong>.</li></ul>"},{"i":"210ee771cb54","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quels sont les facteurs prédictifs dits \"majeurs\" qui justifient l'hospitalisation d'un patient atteint de péricardite aiguë ?","a":"<ul><li>Une <strong>fièvre &gt; 38 °C</strong>.</li><li>Un <strong>épanchement péricardique abondant (&gt; 20 mm)</strong> ou une <strong>tamponnade</strong>.</li></ul>"},{"i":"220cd48df27d","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quels sont les facteurs prédictifs dits \"mineurs\" qui doivent faire envisager l'hospitalisation d'un patient atteint de péricardite aiguë ?","a":"<ul><li>Des symptômes évoluant depuis <strong>plusieurs jours/semaines</strong> avec un début subaigu.</li><li>Une <strong>résistance au traitement anti-inflammatoire depuis &gt; 7 jours</strong>.</li><li>Un patient <strong>immunodéprimé</strong>.</li><li>Un patient sous <strong>anticoagulant</strong>.</li><li>Les suites d'un <strong>traumatisme thoracique</strong>.</li><li>Une <strong>myocardite associée</strong> (révélée par l'élévation des troponines).</li></ul>"},{"i":"6a263afd9c54","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Quelle est la conduite à tenir face à la présence de facteurs prédictifs de complications chez un patient atteint de péricardite aiguë ?","a":"<p>La présence d'un <strong>seul facteur majeur</strong>, ou d'un <strong>faisceau de facteurs mineurs</strong>, justifie à la fois l'hospitalisation du patient et la recherche d'une étiologie non bénigne de la péricardite aiguë.</p>"},{"i":"dbb58f6be4db","n":235,"o":"235-8","u":"Prise en charge","t":"Savoir évaluer les risques de complications nécessitant une hospitalisation","q":"Dans le contexte d'une péricardite aiguë, l'hospitalisation est-elle systématique ?","a":"<p>Non, l'hospitalisation n'est <strong>pas systématique</strong> pour une péricardite aiguë. Elle est envisagée en cas de risque de complication ou d'étiologie inhabituelle.</p>"},{"i":"088cae7c5892","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelles sont les caractéristiques épidémiologiques et le contexte de survenue typiques d'une péricardite aiguë virale ou idiopathique ?","a":"<p>La péricardite aiguë virale ou idiopathique survient typiquement chez le <strong>sujet jeune</strong>, avec une prédominance masculine, sans antécédent cardiologique notable. Elle est souvent précédée d'un <strong>syndrome grippal récent</strong>.</p>"},{"i":"1529e42e296a","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelle est l'implication des recherches virologiques (sérologies, PCR) dans le diagnostic d'une péricardite aiguë typique ?","a":"<p>Dans une forme typique de péricardite aiguë, les recherches virologiques (sérologies, PCR) sont considérées comme <strong>inutiles</strong>. Elles n'ont pas d'implication thérapeutique et le diagnostic est avant tout clinique.</p>"},{"i":"718e33528d93","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Pour la péricardite chez le patient VIH, quelles sont les causes possibles d'épanchement péricardique ?","a":"<p>Chez le patient VIH, la péricardite avec épanchement peut avoir des mécanismes multiples : l'infection par le <strong>VIH lui-même</strong>, une <strong>surinfection bactérienne ou fongique</strong> (chez l'immunodéprimé), ou la présence d'un <strong>lymphome ou d'un sarcome de Kaposi</strong>.</p>"},{"i":"c18b6acd0194","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quels sont les virus fréquemment impliqués dans la péricardite aiguë virale ?","a":"<p>Les virus fréquemment impliqués dans la péricardite aiguë virale incluent les <strong>entérovirus</strong> (Coxsackie A et B), les échovirus, les adénovirus, le CMV, l'EBV, les herpès virus, le parvovirus B19, le VIH, le VHC, les virus influenza et le COVID-19.</p>"},{"i":"e1a1cf7e9259","n":235,"o":"235-9","u":"Etiologies","t":"Connaître l’étiologie de la forme clinique usuelle","q":"Quelle est l'étiologie dominante de la péricardite aiguë dans sa forme clinique usuelle ?","a":"<p>L'étiologie dominante de la péricardite aiguë usuelle est d'origine <strong>virale ou idiopathique</strong>, représentant environ <strong>90 % des cas</strong>.</p>"}]};